const requester = $input.first().json;
const qs = $('Webhook - Get Proposals').first().json.query || {};
if (!requester.id || !requester.active) throw new Error('Invalid session.');
const opportunityIdRaw = parseInt(qs.opportunity_id, 10);
const opportunityId = Number.isInteger(opportunityIdRaw) ? opportunityIdRaw : null;
return [{ json: { opportunityId, requesterId: requester.id, requesterRole: requester.role } }];

const opportunity = $input.item.json;
const requester = $('Validate Session (Save)').first().json;
const body = $('Webhook - Save Proposal').first().json.body || {};

if (!requester.id || !requester.active) throw new Error('Invalid session.');
if (!opportunity || opportunity.assigned_user === undefined) throw new Error('Deal not found.');
if (requester.role !== 'admin' && opportunity.assigned_user !== requester.id) throw new Error('You do not have access to this deal.');

const id = body.id ? parseInt(body.id, 10) : null;
const opportunityId = parseInt(body.opportunity_id, 10);
const title = (body.title || '').toString().trim();
const contentHtml = (body.content_html || '').toString();
const totalAmount = body.total_amount !== undefined && body.total_amount !== null && body.total_amount !== '' ? Number(body.total_amount) : 0;
const emailSubjectInput = (body.email_subject || '').toString().trim();
const emailBodyInput = (body.email_body || '').toString();

// Falls back to a snapshot pulled from the linked contact/company/company
// profile whenever the rep leaves a field blank, so new proposals arrive
// pre-filled but still save their own independent copy on the row.
function pick(bodyVal, fallback) {
  const v = (bodyVal || '').toString().trim();
  return v || (fallback || '').toString().trim();
}

const clientName = pick(body.client_name, opportunity.contact_name);
const clientCompanyName = pick(body.client_company_name, opportunity.company_name);
const clientAddress = pick(body.client_address, opportunity.company_address);
const clientEmail = pick(body.client_email, opportunity.contact_email);
const clientPhone = pick(body.client_phone, opportunity.contact_phone || opportunity.company_phone);
const contractorCompanyName = pick(body.contractor_company_name, opportunity.contractor_company_name);
const contractorEmail = pick(body.contractor_email, opportunity.contractor_email);
const contractorPhone = pick(body.contractor_phone, opportunity.contractor_phone);
const linkedContractTemplateId = body.linked_contract_template_id ? parseInt(body.linked_contract_template_id, 10) : null;

if (!Number.isInteger(opportunityId)) throw new Error('"opportunity_id" is required.');
if (!title) throw new Error('"title" is required.');
if (!contentHtml.trim()) throw new Error('Proposal content is required.');
if (!Number.isFinite(totalAmount) || totalAmount < 0) throw new Error('"total_amount" must be 0 or more.');
if (!linkedContractTemplateId) throw new Error('"linked_contract_template_id" is required.');

return [{
  json: {
    id, opportunityId, title, contentHtml, totalAmount, emailSubjectInput, emailBodyInput,
    clientName, clientCompanyName, clientAddress, clientEmail, clientPhone,
    contractorCompanyName, contractorEmail, contractorPhone, linkedContractTemplateId,
    stageId: opportunity.stage_id, pipelineId: opportunity.pipeline_id, requesterId: requester.id,
  },
}];

const validated = $('Validate & Payload (Save)').first().json;
const flow = $input.item.json;

const emailSubject = validated.emailSubjectInput || flow.proposal_email_subject || `Your proposal is ready — ${validated.title}`;
const emailBody = validated.emailBodyInput || flow.proposal_email_body || 'Hi {{first_name}}, please review your proposal here: {{proposal_link}}';

return [{
  json: {
    id: validated.id,
    opportunityId: validated.opportunityId,
    flowId: flow.id,
    title: validated.title,
    contentHtml: validated.contentHtml,
    totalAmount: validated.totalAmount,
    emailSubject,
    emailBody,
    clientName: validated.clientName,
    clientCompanyName: validated.clientCompanyName,
    clientAddress: validated.clientAddress,
    clientEmail: validated.clientEmail,
    clientPhone: validated.clientPhone,
    contractorCompanyName: validated.contractorCompanyName,
    contractorEmail: validated.contractorEmail,
    contractorPhone: validated.contractorPhone,
    linkedContractTemplateId: validated.linkedContractTemplateId,
    requesterId: validated.requesterId,
  },
}];

const row = $input.item.json;
const requester = $('Validate Session Payload (Send)').first().json;

if (!requester.id || !requester.active) throw new Error('Invalid session.');
if (!row.proposal_id) throw new Error('Proposal not found.');
if (requester.role !== 'admin' && row.assigned_user !== requester.id) throw new Error('You do not have access to this deal.');
if (!row.email) throw new Error("This deal's contact has no email address on file.");

function safeEnv(key) { try { return $env[key] || ''; } catch (e) { return ''; } }
const base = safeEnv('FRONTEND_BASE_URL');
const link = `${base}/documents/proposal/${row.public_token}`;

function money(n) {
  return n != null && n !== '' ? '$' + Number(n).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : '';
}
function dateStr(d) {
  return d ? new Date(d).toLocaleDateString() : '';
}

function fill(template) {
  return (template || '')
    .replace(/{{\s*proposal_link\s*}}/gi, link)
    .replace(/{{\s*contact\.first_name\s*}}/gi, row.first_name || 'there')
    .replace(/{{\s*contact\.last_name\s*}}/gi, row.last_name || '')
    .replace(/{{\s*contact\.email\s*}}/gi, row.email || '')
    .replace(/{{\s*contact\.phone\s*}}/gi, row.phone || '')
    .replace(/{{\s*contact\.address\s*}}/gi, [row.city, row.state].filter(Boolean).join(', '))
    .replace(/{{\s*company\.name\s*}}/gi, row.client_company_name || '')
    .replace(/{{\s*user\.full_name\s*}}/gi, row.owner_name || 'your account team')
    .replace(/{{\s*user\.email\s*}}/gi, row.owner_email || '')
    .replace(/{{\s*user\.phone\s*}}/gi, row.owner_phone || '')
    .replace(/{{\s*user\.company_name\s*}}/gi, row.our_company_name || '')
    .replace(/{{\s*opportunity\.name\s*}}/gi, row.deal_name || '')
    .replace(/{{\s*opportunity\.value\s*}}/gi, money(row.deal_value))
    .replace(/{{\s*opportunity\.created_at\s*}}/gi, dateStr(row.deal_created_at))
    .replace(/{{\s*opportunity\.due_at\s*}}/gi, dateStr(row.deal_due_at))
    .replace(/{{\s*payment\.down_payment_amount\s*}}/gi, money(row.down_payment_amount))
    .replace(/{{\s*payment\.down_payment_paid_at\s*}}/gi, dateStr(row.down_payment_paid_at))
    .replace(/{{\s*payment\.balance_amount\s*}}/gi, money(row.balance_amount))
    .replace(/{{\s*payment\.balance_paid_at\s*}}/gi, dateStr(row.balance_paid_at));
}

const unsubUrl = base + '/unsubscribe/' + (row.unsubscribe_token || '');
const bodyWithFooter = fill(row.email_body) + "\n\nDon't want these emails? Unsubscribe: " + unsubUrl;

return [{ json: { proposalId: row.proposal_id, contactId: row.contact_id, to: row.email, subject: fill(row.email_subject), body: bodyWithFooter } }];

const row = $input.item.json;
const requester = $('Validate Session Payload (Archive)').first().json;

if (!requester.id || !requester.active) throw new Error('Invalid session.');
if (!row.id) throw new Error('Proposal not found.');
if (requester.role !== 'admin' && row.assigned_user !== requester.id) throw new Error('You do not have access to this deal.');

return [{ json: { proposalId: row.id } }];

const row = $input.item.json;
const requester = $('Validate Session Payload (Delete)').first().json;

if (!requester.id || !requester.active) throw new Error('Invalid session.');
if (!row.id) throw new Error('Proposal not found.');
if (requester.role !== 'admin' && row.assigned_user !== requester.id) throw new Error('You do not have access to this deal.');

return [{ json: { proposalId: row.id } }];

const result = $input.first();
if (!result || !result.json || !result.json.id) throw new Error('Proposal not found.');
return [{ json: { success: true } }];

const row = $input.item.json;
if (!row.id) throw new Error('Proposal not found.');

// Priority for the generated contract's title/content: (1) a contract template linked directly
// on THIS proposal template (Proposal editor → Linked contract template) — the most specific,
// deliberate pairing; (2) the fallback template linked on the flow (Settings → Proposal & Contract
// Flow), which applies to any proposal under that flow with no more specific pairing of its own;
// (3) cloning the proposal's own content, for proposals/flows built before Contract Templates existed.
const hasProposalLink = !!row.linked_contract_template_id;
const hasFlowTemplate = !!row.contract_template_id;

return [{
  json: {
    proposalId: row.id,
    opportunityId: row.opportunity_id,
    flowId: row.flow_id,
    alreadyApproved: row.status === 'approved',
    title: hasProposalLink ? row.proposal_template_title : hasFlowTemplate ? row.template_title : row.title,
    contentHtml: hasProposalLink ? row.proposal_template_content_html : hasFlowTemplate ? row.template_content_html : row.content_html,
    thankYouPageId: hasProposalLink ? row.proposal_thank_you_page_id : hasFlowTemplate ? row.flow_thank_you_page_id : null,
    totalAmount: row.total_amount,
    proposalApprovedStageId: row.proposal_approved_stage_id,
    contractEmailSubject: row.contract_email_subject,
    contractEmailBody: row.contract_email_body,
    to: row.email,
    firstName: row.first_name,
    lastName: row.last_name,
    unsubscribeToken: row.unsubscribe_token,
    contactId: row.contact_id,
  },
}];

parameters.query:
INSERT INTO contracts (opportunity_id, proposal_id, flow_id, title, content_html, total_amount, thank_you_page_id, status, created_at, sent_at)
VALUES ($1, $2, $3, $4, $5, $6, $7, 'sent', now(), now())
RETURNING id, public_token;

